    Bug 2008713 - Don't return an OAuth2 provider for hostnames that don't support exchange. r=vineet

    This fixes an OAuth prompt during auto discover when creating an account for providers that just provide a string of scopes. For example when creating a thundermail account, the OAuth prompt would be shown before a config is found.

    Differential Revision: https://phabricator.services.mozilla.com/D296808

diff --git a/mailnews/base/src/OAuth2Providers.sys.mjs b/mailnews/base/src/OAuth2Providers.sys.mjs
index 725836ce07f..291d3df314d 100644
--- a/mailnews/base/src/OAuth2Providers.sys.mjs
+++ b/mailnews/base/src/OAuth2Providers.sys.mjs
@@ -115,6 +115,25 @@ var kHostnames = new Map([
   ],
 ]);

+/**
+ * This list serves as a helper to filter out issuers that don't use an object
+ * to provide type specific scopes but don't support exchange don't offer OAuth
+ * for exchange. If an issuer is registered with an object of scopes it doesn't
+ * need to be declared in this list, because its capabilities are determined by
+ * the keys on the object.
+ *
+ * @type {Set<string>}
+ */
+const kIssuersWithoutExchangeSupport = new Set([
+  "o2.mail.ru",
+  "oauth.yandex.com",
+  "login.yahoo.com",
+  "login.aol.com",
+  "comcast.net",
+  "auth.tb.pro",
+  "auth-stage.tb.pro",
+]);
+
 /**
  * @typedef issuerDetails
  * The information required to perform OAuth authentication with an provider.
@@ -360,6 +379,10 @@ export var OAuth2Providers = {
     }

     if (typeof scopes == "string") {
+      if (type == "exchange" && kIssuersWithoutExchangeSupport.has(issuer)) {
+        // Exchange is not available for this hostname.
+        return undefined;
+      }
       // Scopes not separated into types.
       return { issuer, allScopes: scopes, requiredScopes: scopes };
     }
diff --git a/mailnews/base/test/unit/test_oAuth2Providers.js b/mailnews/base/test/unit/test_oAuth2Providers.js
index e34915dc535..f32ed4ec6f5 100644
--- a/mailnews/base/test/unit/test_oAuth2Providers.js
+++ b/mailnews/base/test/unit/test_oAuth2Providers.js
@@ -298,3 +298,37 @@ add_task(function testIssuerDetails() {
     "returned details should still exactly match the hard-coded ones in this test"
   );
 });
+
+add_task(function testStringScopesWithoutExchangeSupport() {
+  const TEST_FIXTURES = {
+    "gmail.com": false,
+    "imap.mail.ru": false,
+    "imap.yandex.com": false,
+    "yahoo.com": false,
+    "att.net": false,
+    "aol.com": false,
+    "office365.com": true,
+    "graph.microsoft.com": true,
+    "imap.fastmail.com": false,
+    "imap.comcast.net": false,
+    "thundermail.com": false,
+    "stage-thundermail.com": false,
+    "mochi.test": true,
+    "external.test": true,
+    "test.test": false,
+  };
+  for (const [hostname, hasExchangeProvider] of Object.entries(TEST_FIXTURES)) {
+    const result = OAuth2Providers.getHostnameDetails(hostname, "exchange");
+    if (hasExchangeProvider) {
+      Assert.ok(
+        result,
+        `Should find an OAuth2 provider for exchange with ${hostname}`
+      );
+    } else {
+      Assert.ok(
+        !result,
+        `Should not find an OAuth2 provider for exchange with ${hostname}`
+      );
+    }
+  }
+});
